import { test, expect } from "@playwright/test";

test("mock a page response", async ({ page }) => {
  await page.route("https://books.test/", route => route.fulfill({ contentType: "text/html", body: "<h1>Book list</h1>" }));
  await page.goto("https://books.test/");
  await expect(page.getByRole("heading", { name: "Book list" })).toBeVisible();
});
